log = [
    "09:00 ali login OK",
    "09:05 sara login FAILED",
    "09:05 sara login FAILED",
    "09:06 sara login FAILED",
    "09:06 sara login FAILED",
    "09:30 hamza login OK",
    "02:10 admin login FAILED",
]
limit = 3          # itni ya zyada ghalat koshishein = mashkook

failed = {}
for line in log:
    time, user, action, result = line.split()
    if result == "FAILED":
        failed[user] = failed.get(user, 0) + 1

for user, count in failed.items():
    if count >= limit:
        print(f"Khatra: {user} ki {count} ghalat koshishein -> account lock karein")
    else:
        print(f"{user}: {count} ghalat koshish (nazar rakhein)")
